section.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://faion.net/schemas/csharp-dotnet-patterns.json",
  "type": "object",
  "required": ["solution_name", "projects", "use_cases", "arch_tests_pass", "outbox_configured"],
  "properties": {
    "solution_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+$"},
    "projects": {
      "type": "object",
      "required": ["Domain", "Application", "Infrastructure", "Api"],
      "properties": {
        "Domain": {"type": "object", "required": ["references"], "properties": {"references": {"type": "array", "items": {"type": "string"}, "maxItems": 0}}},
        "Application": {"type": "object", "required": ["references"], "properties": {"references": {"type": "array", "items": {"enum": ["Domain"]}}}},
        "Infrastructure": {"type": "object", "required": ["references"], "properties": {"references": {"type": "array", "items": {"enum": ["Domain", "Application"]}}}},
        "Api": {"type": "object", "required": ["references"], "properties": {"references": {"type": "array", "items": {"enum": ["Application", "Infrastructure"]}}}}
      }
    },
    "use_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["feature", "name", "command", "handler", "validator", "response_dto"],
        "properties": {
          "feature": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+$"},
          "name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+$"},
          "command": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+(Command|Query)$"},
          "handler": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Handler$"},
          "validator": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Validator$"},
          "response_dto": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+(Response|Dto)$"},
          "aggregate": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+$"},
          "aggregate_has_public_setters": {"type": "boolean", "const": false},
          "handler_accepts_cancellation_token": {"type": "boolean", "const": true}
        }
      }
    },
    "layer_refs": {
      "type": "object",
      "required": ["domain_has_ef_ref", "domain_has_aspnet_ref", "application_has_ef_ref"],
      "properties": {
        "domain_has_ef_ref": {"type": "boolean", "const": false},
        "domain_has_aspnet_ref": {"type": "boolean", "const": false},
        "application_has_ef_ref": {"type": "boolean", "const": false}
      }
    },
    "pipeline_behaviour_order": {
      "type": "array",
      "items": {"enum": ["Logging", "Validation", "Authorization", "UnitOfWork", "Caching"]}
    },
    "arch_tests_pass": {"type": "boolean", "const": true},
    "outbox_configured": {"type": "boolean", "const": true}
  }
}

example.code:
{
  "solution_name": "billing",
  "projects": {
    "Domain": {"references": ["Infrastructure"]},
    "Application": {"references": ["Domain", "Infrastructure"]},
    "Infrastructure": {"references": ["Domain"]},
    "Api": {"references": ["Application"]}
  },
  "use_cases": [
    {"feature": "ShipOrder", "name": "ShipOrder", "command": "ShipOrderRequest",
     "handler": "OrderService", "validator": "manual-ifs", "response_dto": "OrderEntity",
     "aggregate": "OrderDto", "aggregate_has_public_setters": true,
     "handler_accepts_cancellation_token": false}
  ],
  "layer_refs": {"domain_has_ef_ref": true, "domain_has_aspnet_ref": true,
                 "application_has_ef_ref": true},
  "pipeline_behaviour_order": ["Validation"],
  "arch_tests_pass": false,
  "outbox_configured": false
}
